<?php foreach($form['fields'] as $field):$key=$field['key'];$value=$values[$key]??$field['default']??'';$cond=$field['condition']??null; ?>
<div class="store-custom-field" data-field="<?= e($key) ?>" <?= $cond?'data-condition-field="'.e($cond['field']).'" data-condition-value="'.e($cond['equals']).'"':'' ?>><label for="custom_<?= e($key) ?>"><?= e($field['label']) ?> <?= $field['required']?'*':'' ?></label><?php if($field['help']): ?><p class="hint"><?= e($field['help']) ?></p><?php endif ?>
<?php if(in_array($field['type'],['image','file'],true)): ?><input id="custom_<?= e($key) ?>" type="file" name="upload_<?= e($key) ?>[]" multiple accept="<?= e(implode(',',array_map(fn($x)=>'.'.$x,$field['formats']))) ?>" data-store-file><p class="hint">حداکثر <?= fa($field['max_files']) ?> فایل؛ هر فایل <?= fa($field['max_mb']) ?> مگابایت</p><div data-store-file-list></div><?php foreach(is_array($value)?$value:[] as $fid): ?><label class="store-check"><input type="checkbox" name="custom[<?= e($key) ?>][]" value="<?= (int)$fid ?>" checked>نگه داشتن پیوست #<?= fa($fid) ?></label><?php endforeach ?>
<?php elseif($field['type']==='textarea'): ?><textarea id="custom_<?= e($key) ?>" name="custom[<?= e($key) ?>]" maxlength="<?= (int)$field['max_length'] ?>" rows="4" <?= $field['required']?'required':'' ?>><?= e($value) ?></textarea>
<?php elseif($field['type']==='select'): ?><select id="custom_<?= e($key) ?>" name="custom[<?= e($key) ?>]" <?= $field['required']?'required':'' ?>><option value="">انتخاب کنید</option><?php foreach($field['options'] as $opt): ?><option value="<?= e($opt['value']) ?>" data-extra="<?= (int)$opt['price'] ?>" <?= (string)$value===(string)$opt['value']?'selected':'' ?>><?= e($opt['label']) ?><?= $opt['price']?' (+'.fa(number_format($opt['price'])).' تومان)':'' ?></option><?php endforeach ?></select>
<?php elseif($field['type']==='multi'): ?><fieldset><legend><?= e($field['label']) ?></legend><?php foreach($field['options'] as $opt): ?><label class="store-check"><input type="checkbox" name="custom[<?= e($key) ?>][]" data-extra="<?= (int)$opt['price'] ?>" value="<?= e($opt['value']) ?>" <?= in_array((string)$opt['value'],array_map('strval',is_array($value)?$value:[]),true)?'checked':'' ?>><?= e($opt['label']) ?><?= $opt['price']?' (+'.fa(number_format($opt['price'])).' تومان)':'' ?></label><?php endforeach ?></fieldset>
<?php elseif($field['type']==='checkbox'): ?><input type="hidden" name="custom[<?= e($key) ?>]" value="0"><input id="custom_<?= e($key) ?>" type="checkbox" name="custom[<?= e($key) ?>]" value="1" <?= $value==='1'?'checked':'' ?>>
<?php else: ?><input id="custom_<?= e($key) ?>" name="custom[<?= e($key) ?>]" type="<?= $field['type']==='number'?'number':'text' ?>" value="<?= e($value) ?>" maxlength="<?= (int)$field['max_length'] ?>" <?= $field['required']?'required':'' ?> <?= isset($field['min'])?'min="'.e($field['min']).'"':'' ?> <?= isset($field['max'])?'max="'.e($field['max']).'"':'' ?> <?= $field['type']==='date'?'placeholder="سال/ماه/روز"':'' ?>><?php endif ?></div><?php endforeach ?>
